import test from 'node:test';
import assert from 'node:assert/strict';
import {Game,freshProfile,ticketReward,candidates} from '../src/game.js';
import {Physics} from '../src/physics.js';
const normal=()=>({gold:false,large:false,extra:false,hits:0,after:false});
test('overshoot remains in stock and next stage measures a new net increase',()=>{const g=new Game(freshProfile());g.award(210);g.checkStage();assert.equal(g.phase,'skill');assert.equal(g.stock,610);assert.equal(g.total,210);g.selectSkill(g.choices[0].id);assert.equal(g.stage,2);assert.equal(g.stageStartStock,610);assert.equal(g.progress,0);assert.equal(g.target,1010);assert.equal(g.phase,'playing');});
test('3 second failure timer pauses and resets when stock recovers',()=>{const g=new Game(freshProfile());g.stock=0;g.tick(2);g.pause();g.tick(20);assert.equal(g.zeroTime,2);g.resume();g.addStock(1);assert.equal(g.zeroTime,0);g.stock=0;g.tick(2.9);assert.equal(g.phase,'playing');g.tick(.11);assert.equal(g.phase,'result');});
test('skills offered without duplicates and never at level 5',()=>{const skills={twin:5,gold:5};for(let n=0;n<100;n++){const c=candidates(skills);assert.equal(new Set(c.map(s=>s.id)).size,3);assert.ok(c.every(s=>!skills[s.id]));}});
test('jackpot carries round, count and time across skill choice',()=>{const g=new Game(freshProfile(),0,()=>.5);g.startJackpot();g.jackpot.round=2;g.jackpot.count=6;g.jackpot.time=3;g.award(200);g.checkStage();g.tick(10);g.selectSkill(g.choices[0].id);assert.equal(g.jackpot.round,2);assert.equal(g.jackpot.count,6);assert.equal(g.jackpot.time,3);});
test('10 counts or timeout closes each round and final round ends jackpot',()=>{const g=new Game(freshProfile(),0,()=>0);g.startJackpot();g.jackpot.count=10;g.tick(.01);assert.equal(g.jackpot.round,2);assert.ok(g.jackpot.gap>0);g.jackpot.gap=0;g.jackpot.round=g.jackpot.rounds;g.tick(15);assert.equal(g.jackpot,null);assert.ok(g.rush);});
test('zero payout earns zero and ordinary failure keeps earned rewards',()=>{assert.equal(ticketReward(0,0),0);assert.equal(ticketReward(10000,2),16);assert.equal(ticketReward(10000,2,10),24);const g=new Game(freshProfile());g.award(100);g.finish('lost');assert.equal(g.result.tickets,1);});
test('supply adds stock only and course clears without final skill',()=>{const p=freshProfile();p.upgrades.supply=2;const g=new Game(p);g.award(200);g.checkStage();g.selectSkill(g.choices[0].id);assert.equal(g.stock,610);assert.equal(g.total,200);assert.equal(g.progress,0);g.stage=10;g.award(g.target);g.checkStage();assert.equal(g.phase,'result');assert.equal(g.result.reason,'clear');assert.equal(g.cleared,10);});
test('fractional payout upgrades accrue without losing value to rounding',()=>{const p=freshProfile();p.upgrades.start=1;const g=new Game(p);for(let i=0;i<10;i++)g.hit(normal(),'start');assert.equal(g.total,21);});
test('a large payout cannot skip the next stage without a new net gain',()=>{const g=new Game(freshProfile());g.award(3000);g.checkStage();assert.equal(g.cleared,1);g.selectSkill(g.choices[0].id);assert.equal(g.phase,'playing');assert.equal(g.stage,2);assert.equal(g.progress,0);assert.equal(g.stock,3400);assert.equal(g.target,3800);});
test('normal firing on all three boards produces pocket entries and drains every ball',()=>{for(let course=0;course<3;course++){const g=new Game(freshProfile(),course,()=>.6),world=new Physics(course);let hits=0,lost=0;g.hit=()=>hits++;g.lose=()=>lost++;for(let n=0;n<100;n++){world.spawn(normal(),world.normalPower,0);for(let i=0;i<72;i++)world.step(1/120,g);}for(let i=0;i<2400;i++)world.step(1/120,g);assert.equal(world.balls.length,0);assert.equal(hits+lost,100);assert.ok(hits>5,`course ${course} only ${hits} hits`);console.log(`course ${course+1}: ${hits} physical entries / 100 balls`);}});
test('LCD has no invisible collision shelf or side wall',()=>{const g=new Game(freshProfile()),world=new Physics();world.pins=[];world.spawn(normal());const b=world.balls[0];Object.assign(b,{x:210,y:95,vx:0,vy:120,rail:false});for(let i=0;i<80;i++)world.step(1/120,g);assert.ok(b.y>286,`ball stopped at LCD: ${b.y}`);assert.equal(b.x,210);});
test('pins on the LCD physically deflect balls',()=>{const g=new Game(freshProfile()),world=new Physics();const pin=world.pins.find(p=>p.x>120&&p.x<300&&p.y>140&&p.y<260);assert.ok(pin);world.spawn(normal());const b=world.balls[0];Object.assign(b,{x:pin.x+2,y:pin.y-9,vx:0,vy:100,rail:false});for(let i=0;i<8;i++)world.step(1/120,g);assert.ok(b.hits>0);assert.notEqual(b.vx,0);});
